#include "cfd/solvers/lbm/voxelize.hpp"
#include <cmath>
#include <stdexcept>
namespace cfd::lbm {namespace {using P=cfd::fem::Point3;P sub(P a,P b){return {a.x-b.x,a.y-b.y,a.z-b.z};}P add(P a,P b){return {a.x+b.x,a.y+b.y,a.z+b.z};}P mul(P a,double s){return {a.x*s,a.y*s,a.z*s};}double dotp(P a,P b){return a.x*b.x+a.y*b.y+a.z*b.z;}P crossp(P a,P b){return {a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}bool hit_x(P o,const cfd::io::Triangle3&t){P d{1,0,0},e1=sub(t.b,t.a),e2=sub(t.c,t.a),h=crossp(d,e2);double det=dotp(e1,h);if(std::abs(det)<1e-12)return false;double inv=1/det;P s=sub(o,t.a);double u=inv*dotp(s,h);if(u<0||u>1)return false;P q=crossp(s,e1);double v=inv*dotp(d,q);if(v<0||u+v>1)return false;double dist=inv*dotp(e2,q);return dist>1e-10;}P rotate(P p,P axis,double a){double n=std::sqrt(dotp(axis,axis));if(n<1e-30)return p;axis=mul(axis,1/n);double c=std::cos(a),s=std::sin(a);return add(add(mul(p,c),mul(crossp(axis,p),s)),mul(axis,dotp(axis,p)*(1-c)));}}
std::vector<unsigned char> voxelize_surface(const cfd::io::TriangleSurface&s,const VoxelGrid3D&g){if(s.triangles.empty()||g.nx==0||g.ny==0||g.nz==0||!(g.maximum.x>g.minimum.x)||!(g.maximum.y>g.minimum.y)||!(g.maximum.z>g.minimum.z))throw std::invalid_argument("invalid voxelization inputs");std::vector<unsigned char>mask(g.nx*g.ny*g.nz);double dx=(g.maximum.x-g.minimum.x)/g.nx,dy=(g.maximum.y-g.minimum.y)/g.ny,dz=(g.maximum.z-g.minimum.z)/g.nz;for(std::size_t k=0;k<g.nz;++k)for(std::size_t j=0;j<g.ny;++j)for(std::size_t i=0;i<g.nx;++i){P p{g.minimum.x+(i+.5)*dx,g.minimum.y+(j+.5)*dy+1e-10*dx,g.minimum.z+(k+.5)*dz+2e-10*dx};std::size_t hits=0;for(const auto&t:s.triangles)if(hit_x(p,t))++hits;mask[(k*g.ny+j)*g.nx+i]=static_cast<unsigned char>(hits&1U);}return mask;}
cfd::io::TriangleSurface transform_surface(const cfd::io::TriangleSurface&s,P tr,P axis,double a){cfd::io::TriangleSurface out=s;for(auto&t:out.triangles){t.a=add(rotate(t.a,axis,a),tr);t.b=add(rotate(t.b,axis,a),tr);t.c=add(rotate(t.c,axis,a),tr);}return out;}
}
